import{_ as i,o as a,c as t,a2 as n}from"./chunks/framework.Bqa2y7hU.js";const c=JSON.parse('{"title":"反向代理与 HTTPS","description":"用 Nginx 给 Xiaoyi_QQ_V4 反代 8080、申请 HTTPS 证书，并正确转发 Host 头与调大上传体积。","frontmatter":{"title":"反向代理与 HTTPS","description":"用 Nginx 给 Xiaoyi_QQ_V4 反代 8080、申请 HTTPS 证书，并正确转发 Host 头与调大上传体积。"},"headers":[],"relativePath":"deploy/reverse-proxy.md","filePath":"deploy/reverse-proxy.md","lastUpdated":1789447883000}'),e={name:"deploy/reverse-proxy.md"};function l(p,s,h,k,o,d){return a(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="反向代理与-https-🔒" tabindex="-1">反向代理与 HTTPS 🔒 <a class="header-anchor" href="#反向代理与-https-🔒" aria-label="Permalink to &quot;反向代理与 HTTPS 🔒&quot;">​</a></h1><p>默认情况下控制台直接监听 <code>8080</code>，浏览器访问的是 <code>http://&lt;你的服务器IP&gt;:8080</code>。想让控制台走上域名和 HTTPS，就在前面加一层 Nginx 反向代理。这页给你一份最小可用配置，并说清两个容易踩的坑：<strong>上传体积 / 读超时</strong>和 <strong><code>Host</code> 头转发</strong>。</p><h2 id="_1-最小可用的-nginx-配置" tabindex="-1">1. 最小可用的 Nginx 配置 <a class="header-anchor" href="#_1-最小可用的-nginx-配置" aria-label="Permalink to &quot;1. 最小可用的 Nginx 配置&quot;">​</a></h2><p>假设你已经有一个域名（下文用 <code>example.com</code> 占位）解析到这台服务器。把下面内容存成 <code>/etc/nginx/sites-available/xiaoyi-qq-c</code>：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    server_name </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">example.com;          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 换成你自己的域名</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 上传体积：插件包上传需要放宽，否则大包会被 Nginx 直接 413 拒绝</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    client_max_body_size </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200m</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> / </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:8080;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 必须转发 Host，否则程序算出的回调地址会退化成内网地址</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Host              $host;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Real-IP         $remote_addr;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-For   $proxy_add_x_forwarded_for;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-Proto $scheme;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 读超时：插件包上传 / 下载耗时较长，默认 60s 容易断</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_read_timeout </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   300s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_send_timeout </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   300s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_connect_timeout </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30s</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>启用配置并重载：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 建软链启用站点，检查语法后重载</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/nginx/sites-available/xiaoyi-qq-c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/nginx/sites-enabled/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span></code></pre></div><h2 id="_2-两处必须放大的参数" tabindex="-1">2. 两处必须放大的参数 <a class="header-anchor" href="#_2-两处必须放大的参数" aria-label="Permalink to &quot;2. 两处必须放大的参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>为什么</th></tr></thead><tbody><tr><td><code>client_max_body_size</code></td><td>插件包上传走这个入口。默认只有 1m，包稍大就会被 Nginx 挡掉</td></tr><tr><td><code>proxy_read_timeout</code> / <code>proxy_send_timeout</code></td><td>插件包上传、下载都是长耗时请求，默认 60s 会在传输中途断开</td></tr></tbody></table><p>这两项都写在上面的配置里了，装插件遇到「上传没反应」或「413」时先回头看这里。</p><h2 id="_3-https-证书" tabindex="-1">3. HTTPS 证书 <a class="header-anchor" href="#_3-https-证书" aria-label="Permalink to &quot;3. HTTPS 证书&quot;">​</a></h2><p>证书用 <code>certbot</code> 或你服务器面板自带的一键申请都行，一行带过：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># certbot 申请并自动改 Nginx 配置（Debian/Ubuntu 系）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certbot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3-certbot-nginx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certbot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span></span></code></pre></div><p>签发完成后 certbot 会自动改写上面的 server 块，加上 443 监听与证书路径，并把 HTTP 跳转到 HTTPS。</p><h2 id="_4-关键-转发-host-头" tabindex="-1">4. 关键：转发 <code>Host</code> 头 <a class="header-anchor" href="#_4-关键-转发-host-头" aria-label="Permalink to &quot;4. 关键：转发 \`Host\` 头&quot;">​</a></h2><p>这是最容易出问题的一点。程序生成回调地址时会参考请求的 <code>Host</code>，如果反向代理<strong>没有转发原始 <code>Host</code></strong>：</p><ul><li>回调地址会退化成 <code>127.0.0.1</code> 这类内网地址；</li><li>平台侧回调打不进来，QQ 平台的消息收不到。</li></ul><p>所以配置里的这一行不能省：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Host $host;</span></span></code></pre></div><p>配好后可以打开控制台的「平台设置 → 站点」核对一下生成的公网地址是不是你的域名。</p><h2 id="_5-让服务只监听本地-安全建议" tabindex="-1">5. 让服务只监听本地（安全建议） <a class="header-anchor" href="#_5-让服务只监听本地-安全建议" aria-label="Permalink to &quot;5. 让服务只监听本地（安全建议）&quot;">​</a></h2><p>既然前面有 Nginx 兜着，就没必要再把 <code>8080</code> 暴露到公网。把监听地址改成回环地址即可：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">admin_listen = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1:8080&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 只允许本机访问，由 Nginx 转发进来</span></span></code></pre></div><p>改完重启服务生效：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">8081 不要一起藏到本地</p><p><code>8081</code> 是<strong>适配器数据面端口</strong>，不是给浏览器用的。QQ 平台侧的连接（尤其是 <strong>OneBot 11 的反向 WebSocket</strong>）需要直接连到 <code>8081</code>，这是机器人与平台之间的通道。</p><p>如果你把 <code>data_listen</code> 也改成 <code>127.0.0.1:8081</code>，对外就只剩 Nginx 一个入口，<strong>OneBot 反向 WS 将无法建立连接</strong>。</p><p>正确做法：</p><ul><li><strong>只用 QQ 官方适配器</strong>（WebSocket 网关 / Webhook 回调）→ 可以只监听本地，回调走 Nginx 转发；</li><li><strong>要用 OneBot 11</strong> → <code>8081</code> 必须保持对外可访问（或者你自己在 Nginx 上为它单独做一层 stream / WebSocket 转发）。详见 <a href="/RuaBot.Doc/platforms/qq-onebot">QQ OneBot 11</a>。</li></ul></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/platforms/qq-onebot">QQ OneBot 11</a></li><li><a href="/RuaBot.Doc/platforms/callback">回调地址与公网域名</a></li><li><a href="/RuaBot.Doc/deploy/ops">备份与运维</a></li></ul>`,28)])])}const g=i(e,[["render",l]]);export{c as __pageData,g as default};
